head.script:
scwin.select1_onchange = function() {
    console.log(num1++);
};
scwin.select2_onviewchange = function(info) {
    console.log(num2++);
};
scwin.select3_onlabelclick = function(index, checked, value) {
    console.log(num3++);
};
scwin.select4_oncheckboxclick = function(index, checked, value) {
    console.log(num4++);
};
scwin.onpageload = function() {
    window.num1 = 0;
    window.num2 = 0;
    window.num3 = 0;
    window.num4 = 0;
}

scwin.___fireOver = function(id) {
    node = WebSquare.wUnit.getDomById($p.id + id);
    if (document.createEventObject) {
        node.fireEvent("onmouseover");
    } else if (document.createEvent) {
        var evt = document.createEvent("MouseEvents");
        evt.initEvent("mouseover", true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.onmouseover == "function") {
        node.onmouseover();
    }
}
scwin.checkVal = function() {
	return WebSquare.wUnit.getDomById('select1').getAttribute('useCheckboxTitle') === null;
};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.___fireOver(('select1_input_0'))");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
